import{_ as t,o as a,c as r,ak as o}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"How we can work in parallel","description":"Historical snapshot taken before v2 adoption on October 23, 2026. Not active requirements or current progress. See the adoption archive.","frontmatter":{"title":"How we can work in parallel","description":"Historical snapshot taken before v2 adoption on October 23, 2026. Not active requirements or current progress. See the adoption archive.","source":"docs/archive/pre-v2-adoption-2026-10-23/docs/planning/agentic-parallel-execution-plan.md","category":"Archive","sourceUpdated":"2026-10-23T16:51:22+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/archive/pre-v2-adoption-2026-10-23/docs/planning/agentic-parallel-execution-plan.md","filePath":"content/docs/archive/pre-v2-adoption-2026-10-23/docs/planning/agentic-parallel-execution-plan.md"}'),n={name:"content/docs/archive/pre-v2-adoption-2026-10-23/docs/planning/agentic-parallel-execution-plan.md"};function i(s,e,d,c,h,l){return a(),r("div",null,[...e[0]||(e[0]=[o('<div><h1 id="how-we-can-work-in-parallel">How we can work in parallel<a class="header-anchor" href="#how-we-can-work-in-parallel" aria-label="Link to this section">​</a></h1><blockquote><p>Historical snapshot taken before v2 adoption on October 23, 2026. Not active requirements or current progress. See the <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/readme.html">adoption archive</a>.</p></blockquote><p>Updated October 13, 2026. The <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/docs/kanban-plan-draft.html">task plan</a> has 56 small cards, one owner per card, and a clear list of work that must finish first. The <a href="https://github.com/Kamiyon-Studio/Chainy/blob/main/tools/team-board/subtasks.json">card data</a> supplies the same plan to the live board.</p><p>The game scope stays as Christian&#39;s verified design describes it: explorable levels, Quiz, Wordle and BlockMatch. The three games&#39; exact rules are still open. <strong>Beta testing is fixed for November 3–6, 2026. Pre-final defense is fixed for November 21, 2026.</strong> Keep October 26–30 for integration, October 31–November 2 for device checks, and November 17–20 for rehearsal. The team has not confirmed its available hours, so these dates are planning targets rather than a promise that every card fits.</p><h2 id="who-owns-each-kind-of-work">Who owns each kind of work<a class="header-anchor" href="#who-owns-each-kind-of-work" aria-label="Link to this section">​</a></h2><p>An AI helper can prepare work for one card, but the named teammate remains responsible for checking and accepting it. Keep the card with that person; do not add an AI helper or another person as a second owner.</p><table><thead><tr><th>Role agent</th><th>Cards belong to</th><th>Do not hand the agent</th></tr></thead><tbody><tr><td>Project and Design — Sherwin Limosnero</td><td>School/team decisions, priorities, schedule and player-experience decisions</td><td>Writing formal project documents, code, screen implementation or art production</td></tr><tr><td>Technical — Christian Jude Villaber</td><td>Game code, SQLite saving, Android builds, and technical integration/checks</td><td>Art, player-screen implementation or formal document writing</td></tr><tr><td>Art — Luis Cabrido III</td><td>The approved game art, export files and their source/license notes</td><td>Game code, screen implementation or document writing</td></tr><tr><td>Documentation — Sean Matthew Narvaez</td><td>All formal project documents, learner instructions, test forms, evidence write-ups and manuscript</td><td>Making Sherwin&#39;s design decisions, coding or producing art</td></tr><tr><td>UI — Miguel De Leon</td><td>Approved game screens and touch controls</td><td>Game rules, data/save logic, general art production or formal documents</td></tr></tbody></table><p>If work crosses roles, the first owner links their decision, text, art or technical result. A separate card for the next role depends on it. For example: Sherwin decides how each mini-game works → Christian confirms that the rules can be built within the shared game/data setup → Sean writes the approved rules sheet. These are three separate cards, not one shared assignment.</p><h2 id="work-order-and-safe-parallel-starts">Work order and safe parallel starts<a class="header-anchor" href="#work-order-and-safe-parallel-starts" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Step</th><th>What the role agents can work on</th><th>What must be ready next</th></tr></thead><tbody><tr><td><strong>1. Confirm the starting facts</strong></td><td>Sherwin checks school requirements, available work time and beta arrangements. Christian confirms the actual game project folder, its version, the Unity editor version and the Android build steps. Sean can update current-scope chapters using the approved design.</td><td>Game-code agents wait until Christian can open the actual game project and reproduce an Android build. Do not guess a version, source revision, school answer or result.</td></tr><tr><td><strong>2. Agree on the game rules</strong></td><td>Sherwin decides Quiz scoring/pass behavior, the Wordle word list/guess limit, and BlockMatch matching/win behavior. Christian checks how each decision fits the shared game and save setup.</td><td>Keep any unagreed choice open. Sean&#39;s short rules sheet is a follow-up card after the Design/Tech decisions.</td></tr><tr><td><strong>3. Build the shared pieces</strong></td><td>Once their inputs are ready, Christian works on game flow, SQLite and saved results; Miguel on assigned screens; Luis on approved art; Sean on approved learning text, forms and instructions; Sherwin on school/team decisions.</td><td>Only run work together when the inputs are stable and the people are not changing the same game file or deciding the same outcome. Christian assigns non-overlapping code files before parallel coding starts.</td></tr><tr><td><strong>4. Finish and check each mode</strong></td><td>Christian builds Quiz, Wordle and BlockMatch from the agreed rules and shared save path. Luis hands over art; Miguel checks player-screen behavior; Sean prepares mode instructions and the approved beta protocol.</td><td>Each card&#39;s listed prerequisite must be done first. Christian integrates the working features during the October 26–30 window.</td></tr><tr><td><strong>5. Beta and pre-final</strong></td><td>Christian runs technical checks; Miguel checks the screens and touch controls; Sherwin coordinates the school event; Sean records approved procedures and actual evidence. After the beta, Sean writes from the real results and Sherwin coordinates the rehearsal.</td><td>School permission and the approved protocol must be ready before testing. Keep the fixed November dates and rehearsal window. Do not use task counts as proof of readiness.</td></tr></tbody></table><p>The separate game repository is <a href="https://github.com/Kamiyon-Studio/Chainy-Game">Kamiyon-Studio/Chainy-Game</a>. This planning work did not verify a working checkout, version, Unity editor or Android build. Until Christian&#39;s source/build card supplies that evidence, agents can work on approved decisions, documents, project coordination and art that has a clear approved brief; they should not claim to have implemented the game.</p><h2 id="give-an-ai-helper-one-card-at-a-time">Give an AI helper one card at a time<a class="header-anchor" href="#give-an-ai-helper-one-card-at-a-time" aria-label="Link to this section">​</a></h2><p>Start with a card whose prerequisites are complete. Give the helper its title, description, completion check, reference links and this role boundary. For code or art files, use a separate copy of the project or reserve different files so two helpers cannot overwrite one another. Ask the helper to return the finished work, what it checked, and any blocker. The named teammate checks the card&#39;s completion conditions and adds the evidence link before moving it to Done. If the result belongs to another role, use the separate handoff card instead of letting the helper edit that role&#39;s work.</p><p>The full card list shows every task and its owner. Its original planning windows are retained; the team still needs to confirm each person&#39;s actual availability. If an early checkpoint slips, Sherwin and Christian review the remaining workload together while preserving the integration, device-check, beta and rehearsal time. The school&#39;s stated completion requirement and rubric still need direct clarification; completing cards does not calculate that percentage.</p></div>',1)])])}const m=t(n,[["render",i]]);export{u as __pageData,m as default};
